void ScriptSession::beginCorpse(UnitState& u,bool immediate){
    auto& data=definitions();float flags=data.number(u.type,"UnitData","deathType"),death=data.number(u.type,"UnitData","death");if(flags<0 || flags>3 || flags!=std::floor(flags) || death<0 || death>86400)throw std::runtime_error("Unit death definition outside supported range");CorpseState state;state.flags=(u.illusion || u.noCorpse || u.exploded)?0:unsigned(flags);state.death=death;state.flesh=u.hero?gameplayNumber("DissipateTime",3):u.building?gameplayNumber("StructureDecayTime",30):gameplayNumber("DecayTime",2);state.bone=u.hero || u.building?0:gameplayNumber("BoneDecayTime",88);if(state.flesh<0 || state.flesh>86400 || state.bone<0 || state.bone>86400)throw std::runtime_error("Corpse decay duration outside supported range");if(immediate){state.elapsed=state.death;state.phase=CorpseState::Phase::Flesh;u.animation="Decay Flesh";u.animationTime=0;++u.animationGeneration;}u.corpse=state;corpseHandles_.insert(u.handle);
}
void ScriptSession::clearCorpse(UnitState& u){if(!u.corpse)return;corpseHandles_.erase(u.handle);u.corpse.reset();u.animation="Stand";u.animationIndex.reset();u.animationQueue.clear();u.animationTime=0;++u.animationGeneration;++fogRevision_;}
bool ScriptSession::corpseAvailable(std::uint32_t id,std::uint32_t claimant){
    if(!alive(id,NativeKind::Unit))return false;auto u=units_.at(id);return !u->rebirth && !u->removing && !u->hidden() && !u->hero && !u->building && !u->illusion && number(u->life)<=0 && u->corpse && u->corpse->flags && !u->corpse->consumed && !u->corpse->gone && u->corpse->elapsed>=u->corpse->death && (!u->corpse->claimedBy || u->corpse->claimedBy==claimant);
}
bool ScriptSession::corpseTarget(const UnitState& caster,const UnitState& target,const SpellInfo& s,bool visibility){
    if(s.kind==SpellKind::LoadCorpse)return canLoad(caster,target) && (!visibility || unitVisibleTo(target.handle,caster.owner));if(!corpseAvailable(target.handle,caster.handle) || (visibility && !unitVisibleTo(target.handle,caster.owner)))return false;if(s.kind!=SpellKind::Cannibalize && !(target.corpse->flags&1))return false;auto classes=target.classifications(definitions().unitClasses(target.type));auto& allowed=s.allowed;bool air=target.movementType=="fly";if((allowed.contains("air") || allowed.contains("ground")) && (air?!allowed.contains("air"):!allowed.contains("ground")))return false;if(allowed.contains("organic") && classes.find("mechanical")!=std::string::npos)return false;if(s.kind==SpellKind::AncestralSpirit && classes.find("tauren")==std::string::npos)return false;if(allowed.contains("player") && target.owner!=caster.owner)return false;bool hostile=enemy(caster.owner,target.owner),relationships=allowed.contains("friend") || allowed.contains("enemy") || allowed.contains("neutral");if(relationships && !((!hostile && allowed.contains("friend")) || (hostile && allowed.contains("enemy")) || (target.owner>=12 && allowed.contains("neutral"))))return false;if(s.kind==SpellKind::Cannibalize && number(caster.life)>=number(caster.maxLife))return false;return true;
}
std::vector<std::uint32_t> ScriptSession::corpseTargets(const UnitState& caster,const SpellInfo& s,WorldPoint point,float radius){
    if(radius<0)radius=s.kind==SpellKind::Cannibalize?std::max(s.range,number(caster.acquireRange)):s.area>0?s.area:s.range;std::vector<std::tuple<std::int64_t,float,std::uint32_t>> sorted;for(auto id:corpseHandles_){if(!alive(id,NativeKind::Unit))continue;auto corpse=units_.at(id);float distance=std::hypot(number(corpse->x)-number(point.x),number(corpse->y)-number(point.y));if(distance>radius+corpse->collision || !corpseTarget(caster,*corpse,s))continue;std::int64_t priority=s.kind==SpellKind::Resurrection || s.kind==SpellKind::AnimateDead?-std::int64_t(corpse->level):0;sorted.emplace_back(priority,distance,id);}std::sort(sorted.begin(),sorted.end());std::vector<std::uint32_t> result;for(auto [priority,distance,id]:sorted)result.push_back(id);return result;
}
void ScriptSession::releaseCorpseClaim(std::uint32_t id,std::uint32_t caster,std::uint64_t ticket){if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);if(u->corpse && u->corpse->claimedBy==caster && u->corpse->claimTicket==ticket){u->corpse->claimedBy=0;u->corpse->claimTicket=0;}}
void ScriptSession::consumeCorpse(std::uint32_t id){if(!corpseAvailable(id,alive(id,NativeKind::Unit) && units_.at(id)->corpse?units_.at(id)->corpse->claimedBy:0))return;auto u=units_.at(id);u->corpse->consumed=true;u->corpse->gone=true;removeUnit(id);}
void ScriptSession::graveyardTick(std::uint32_t id,double delta){
    if(!alive(id,NativeKind::Unit))return;auto unit=units_.at(id);if(!unit->graveyard)return;auto source=sourceAbility(*unit,"Agyd");if(!source.first){unit->graveyard.reset();return;}auto& data=definitions();auto suffix=std::to_string(source.second);float maximum=data.number(source.first,"AbilityData","DataA"+suffix),graveRadius=data.number(source.first,"AbilityData","DataB"+suffix),corpseRadius=data.number(source.first,"AbilityData","DataC"+suffix),interval=data.number(source.first,"AbilityData","Cool"+suffix);auto type=data.field(source.first,"AbilityData","UnitID"+suffix);if(!std::isfinite(maximum) || maximum<1 || maximum>4096 || maximum!=std::floor(maximum) || !std::isfinite(graveRadius) || graveRadius<0 || !std::isfinite(corpseRadius) || corpseRadius<0 || !std::isfinite(interval) || interval<0 || interval>86400 || type.size()!=4 || !data.contains(ObjectData::code(type)))throw std::runtime_error("Invalid graveyard source ability");auto& state=*unit->graveyard;if(state.ability!=source.first){state=GraveyardState{};state.ability=source.first;}if(state.level!=source.second){state.level=source.second;state.elapsed=0;}std::erase_if(state.bodies,[&](auto body){if(!alive(body,NativeKind::Unit))return true;auto target=units_.at(body);return target->removing || target->hidden() || target->transport || number(target->life)>0 || !target->corpse || target->corpse->consumed || target->corpse->gone || std::hypot(number(target->x)-number(unit->x),number(target->y)-number(unit->y))>corpseRadius;});if(unit->paused || unit->hidden() || unit->removing || unit->construction || unit->unsummon || unit->abilitiesDisabled() || unit->illusion || number(unit->life)<=0)return;if(state.bodies.size()>=unsigned(maximum)){state.elapsed=0;return;}state.elapsed+=delta;if(state.elapsed<std::max(double(interval),1./32))return;state.elapsed=0;float angle=float(state.emitted++)*2.39996323f,radius=std::min(graveRadius*.65f,corpseRadius);WorldPoint point{jass::Real::fromBits(std::bit_cast<std::uint32_t>(number(unit->x)+std::cos(angle)*radius)),jass::Real::fromBits(std::bit_cast<std::uint32_t>(number(unit->y)+std::sin(angle)*radius))};auto body=createCorpse(unit->owner,ObjectData::code(type),point,unit->facing);if(alive(id,NativeKind::Unit) && unit->graveyard && alive(body.bits,NativeKind::Unit))unit->graveyard->bodies.push_back(body.bits);
}
void ScriptSession::corpsesTick(double delta){
    std::vector<std::uint32_t> actors(corpseHandles_.begin(),corpseHandles_.end());for(auto id:actors){if(!alive(id,NativeKind::Unit)){corpseHandles_.erase(id);continue;}auto u=units_.at(id);if(!u->corpse || number(u->life)>0){clearCorpse(*u);continue;}if(u->rebirth)continue;auto& c=*u->corpse;if(c.claimedBy){bool active=alive(c.claimedBy,NativeKind::Unit) && units_.at(c.claimedBy)->cast && units_.at(c.claimedBy)->cast->ticket==c.claimTicket && units_.at(c.claimedBy)->cast->target==id;if(!active){c.claimedBy=0;c.claimTicket=0;}}if(!u->paused && !u->transport && !c.claimedBy){if(u->decaySuspended){if(c.elapsed<c.death)c.elapsed=std::min(c.death,c.elapsed+delta);}else c.elapsed+=delta;}auto phase=CorpseState::Phase::Death;if(c.elapsed>=c.death){if(u->noCorpse || u->exploded || u->illusion)phase=CorpseState::Phase::Gone;else if(u->hero)phase=c.elapsed>=c.death+c.flesh?CorpseState::Phase::Gone:CorpseState::Phase::Dissipate;else if(!(c.flags&2))phase=(c.flags&1)?CorpseState::Phase::Body:CorpseState::Phase::Gone;else if(u->building)phase=c.elapsed>=c.death+c.flesh?CorpseState::Phase::Gone:CorpseState::Phase::Flesh;else phase=c.elapsed>=c.death+c.flesh+c.bone?CorpseState::Phase::Gone:c.elapsed>=c.death+c.flesh?CorpseState::Phase::Bone:CorpseState::Phase::Flesh;}if(c.consumed)phase=CorpseState::Phase::Gone;if(phase!=c.phase){c.phase=phase;u->animation=phase==CorpseState::Phase::Flesh?"Decay Flesh":phase==CorpseState::Phase::Bone?"Decay Bone":phase==CorpseState::Phase::Dissipate?"Dissipate":"Death";u->animationIndex.reset();u->animationQueue.clear();u->animationTime=phase==CorpseState::Phase::Body?c.death:0;if(phase==CorpseState::Phase::Flesh || phase==CorpseState::Phase::Bone || phase==CorpseState::Phase::Dissipate)++u->animationGeneration;}if(phase==CorpseState::Phase::Gone){c.gone=true;++fogRevision_;if(c.flags&2)unitEvent(id,21,54);if(!alive(id,NativeKind::Unit) || number(u->life)>0 || !u->corpse || !u->corpse->gone)continue;if(u->hero)corpseHandles_.erase(id);else removeUnit(id);}}
}
void ScriptSession::bindCorpseNatives(){
    bind("GetDecayingUnit","unit",{},[this](auto& vm,auto){return vm.handle("unit",!contexts_.empty() && (contexts_.back().event==21 || contexts_.back().event==54)?contexts_.back().triggerUnit:0);});
    bind("CreateCorpse","unit",{"player","integer","real","real","real"},[this](auto&,auto a){return createCorpse(playerId(a[0]),a[1].bits,{jass::Real::fromBits(a[2].bits),jass::Real::fromBits(a[3].bits)},jass::Real::fromBits(a[4].bits));});
    bind("UnitSuspendDecay","nothing",{"unit","boolean"},[this](auto& vm,auto a){unit(a[0]).decaySuspended=a[1].bits!=0;return vm.nothing();});
    bind("SetUnitExploded","nothing",{"unit","boolean"},[this](auto& vm,auto a){auto& u=unit(a[0]);u.exploded=a[1].bits!=0;if(u.exploded && u.corpse)u.corpse->flags=0;return vm.nothing();});
}
